"""Audit fixed mixed-support predictions and disclose all numerical amendments."""
from pathlib import Path
import collections,json,pickle,shutil,sys
import numpy as np
sys.path.insert(0,str(Path(__file__).parent));import run as C
R,O,A,REPO=C.R,C.O,C.A,C.REPO

def main():
    C.scored();assert not (O/'complete.json').exists() and C.read(O/'review.json')['passed'];checks=0;reuse=0;positive_constraints=0
    for path in sorted((O/'models').glob('*.npz')):
        pool=path.stem;cp=np.load(path);z=np.load(C.Q/'qualified_inputs'/path.name);t=cp['theta'];fallback=bool(cp['fallback_KEEP'][0]);alpha=float(cp['alpha'][0]);value,g=C.objective(t,z['X'],z['y'],z['weight'],z['b']);sv,sg,h=C.stable_math(t,z['X'],z['y'],z['weight'],z['b']);assert abs(value-sv)<1e-10 and np.allclose(g,sg,atol=1e-7,rtol=1e-7)
        if not fallback:assert abs(g).max()<1e-3
        if pool!='f2_s0':assert C.sha(path)==C.sha(C.P.O/'models'/path.name);reuse+=1
        stop=z['calibration_X']@t[:-1]+t[-1]+z['calibration_b'];y=z['calibration_y']>0;score=z['calibration_b']+alpha*(stop-z['calibration_b']);assert np.all(score[y]>=0);positive_constraints+=int(y.sum());public=np.load(C.INPUT_PUBLIC/path.name);saved=np.load(O/'held_predictions'/path.name);endpoint=np.sum(public['X']*t[:-1],axis=1)+t[-1]+public['b'];expected=public['b']+alpha*(endpoint-public['b']);assert np.allclose(expected,saved['logit'],atol=1e-10,rtol=1e-10) and np.array_equal(saved['keep'],saved['logit']>=0);checks+=len(expected)
    assert (reuse,checks,positive_constraints)==(11,4681,90)
    for phase,name,pubfile in [('trained','trained_freeze.json','pre_score_publication.json'),('scored','scored_freeze.json','pre_join_publication.json')]:
        pub=C.read(O/pubfile);assert C.git('show',pub['git_sha']+':'+(A/phase/name).relative_to(REPO).as_posix())==(O/name).read_bytes()
    assert not (C.P.O/'score_started.json').exists() and not (R/'outputs/grid226_context_numeric/score_started.json').exists();cases={r['sample_id']:r for r in pickle.loads((R/'outputs/grid102_search_rl/cases.pkl').read_bytes())};task=C.read(R/'outputs/grid102_search_rl/design.json');fee,scale=task['cost_per_query'],task['gain_scale'];tr=C.read(O/'oof_trajectories.json')
    for row in tr:
        c=cases[row['sample_id']];j=row['baseline_stop']+int(row['append']);assert row['gain']==float(c['gains'][:j].sum()) and row['queries']==int(c['queries'][:j].sum()) and row['chosen_pool_id']==c['chosen'][j];assert abs(row['net_utility']-(row['gain']-fee*row['queries'])/scale)<1e-12;assert row['actions']==[1]*j+([0] if j<len(c['states']) else [])
    assert len(tr)==21402;changes=C.read(O/'changed_choices.json');assert len(changes)==47;metrics=C.read(O/'search_metrics.json');ncases={d['date']:d['cases'] for d in metrics['GATE_seed0']['per_date']};decomp=[];repeat=collections.defaultdict(list);negativecalls=collections.defaultdict(float);profit_loss=collections.defaultdict(float)
    for row in changes:
        if not row['MIXED_append'] and row['actual_next_NET']<=0:repeat[row['sample_id'],row['position']].append(row)
        if row['NET_delta']<0:negativecalls[row['physical_state_group']]+=-row['NET_delta']/(3*16*ncases[row['date']])
        if not row['MIXED_append'] and row['actual_next_NET']>0:profit_loss[row['physical_state_group']]+=row['actual_next_NET']/(3*16*ncases[row['date']])
    repeated=[dict(sample_id=k[0],position=k[1],call=rr[0]['physical_state_group'],seeds=sorted({r['seed'] for r in rr}),query_deltas=[r['query_delta'] for r in rr],independent_cases=False) for k,rr in repeat.items() if len({r['seed'] for r in rr})>=2];assert len(repeated)==2
    paired=C.read(O/'paired_summary.json');family=C.read(O/'family_summary.json');counts=C.read(O/'gate_counts.json')
    for seed in range(3):
        rr=[r for r in changes if r['seed']==seed];positive=sum(max(r['NET_delta'],0)/(16*ncases[r['date']]) for r in rr);negative=sum(min(r['NET_delta'],0)/(16*ncases[r['date']]) for r in rr);ref=next(r for r in paired if r['base']=='STOP_ONLY' and r['seed']==seed)['macro_delta']['mean_net_utility'];assert abs(positive+negative-ref)<1e-12;decomp.append(dict(seed=seed,positive_contribution=positive,negative_contribution=negative,total=positive+negative,changes=len(rr),gain_changes=[r['gain_delta'] for r in rr if r['gain_delta']!=0]))
    newloss=sum(profit_loss.values());top=sorted(profit_loss.items(),key=lambda x:-x[1]);C.save('effect_decomposition.json',dict(per_seed=decomp,repeated_unprofitable_savings=repeated,new_profitable_loss_by_call=dict(top),top_new_profitable_loss_share=top[0][1]/newloss,negative_NET_by_call=dict(sorted(negativecalls.items(),key=lambda x:-x[1]))));C.save('decision.json',dict(retain208_main_and222_tradeoff=True,do_not_replace222_by_mixed=True,keep_two_seed_small_positive_signals=True,NET_vs222_signs=[-1,1,1],two_zero_gain_states_saved_in_two_seeds=repeated,major_negative_case='2037-01-05_101|call001 in f0_s0 (not numerically repaired f2_s0)',next='Read-only decompose47 changes and check source/held public-feature scales and numerical margin robustness. Preserve positive pockets and dominant loss;qualify any reduced-public-input correction only before future fitting,not by heldthreshold selection.',no_new_physics_or_test=True))
    lines=['# GRID227：停止前辅助经验对照与数值修订记录','','本轮按GRID224 revision02加入原停止前正负经验，复用旧222 ANCHORED作为STOP_ONLY、208作为GATE。当前有效MIXED模型有一次明确记录的单池数值求解修订；原225和226均保持未评分，不能宣称其原协议通过。','', '## 主要结果','','|指标|原208|原STOP_ONLY（222）|加入辅助经验MIXED|','|---|---:|---:|---:|']
    for key,label in [('mean_queries','候选查询'),('mean_gain','即时增益'),('mean_net_utility','固定费代理净效用'),('gain_capture','局部收益保留比例'),('action_match_rate','完整局部搜索动作一致率')]:lines.append(f"|{label}|{family['GATE'][key]:.9f}|{family['STOP_ONLY'][key]:.9f}|{family['MIXED'][key]:.9f}|")
    lines+=['', '相比222，两个种子的代理净效用有小幅提高，种子0下降更大，平均仍下降。原回本保留39/55变为38/55；新增恢复2条、失去3条。当前混合经验方案不替换222或208。','', '|种子|MIXED减STOP_ONLY净效用|查询|即时增益|','|---|---:|---:|---:|']
    for d in [r for r in paired if r['base']=='STOP_ONLY']:m=d['macro_delta'];lines.append(f"|{d['seed']}|{m['mean_net_utility']:.9f}|{m['mean_queries']:.6f}|{m['mean_gain']:.10f}|")
    lines+=['','## 小改善仍值得保留','','种子1的15条变化均未改变即时增益或动作一致性，主要收益来自减少无效查询；种子2恢复了2037-11-16_101 call001的2条回本前缀，但也付出额外查询。它们不是独立新场景。','', '另有两个相同状态在种子1、2重复取消无利追加，分别少4和3个候选查询。这些局部线索保留，不因平均未赢而丢弃，也不挑出好种子作为最终方法。','', '|状态|物理调用|种子|每条查询变化|','|---|---|---|---|']
    for r in repeated:lines.append(f"|{r['sample_id']}|{r['call']}|{','.join(map(str,r['seeds']))}|{','.join(map(str,r['query_deltas']))}|")
    lines+=['', f"种子0新增误删3条回本机会，其中2037-01-05_101 call001占新增回本损失的{top[0][1]/newloss:.2%}。这一大损失来自f0_s0，和数值修订的f2_s0不是同一个池，不能将它解释成修订求解器造成。",'', '## 数值资格：没有放宽标准或重训合格项','','GRID225的11模型+11步长已完成，但f2_s0在原固定原始梯度阈值0.001上得到0.001813，故停止未评分。辅助输入沿用原标准化，该池最大绝对值约2088511，导致数值条件变差。其余10个学习池与KEEP原样保存。','', '另立GRID226，只准一次完整Newton更新；虽降低目标值，原始梯度升至0.004068，按该协议停止，不做第二次尝试，也未评分。该失败和候选权重完整保留。','', 'GRID227在任何混合模型评分之前封存独立数值协议：同一凸目标的稳定计算、精确Hessian与固定回溯Newton，最多50次迭代。先通过2个高尺度合成问题。只处理原未合格f2_s0，其他10模型和KEEP连同步长逐字节复用，未重训合格项；源225/226不修改。','', 'f2_s0实际用了2次Newton迭代，原始梯度降至1.0262e-7，低于原0.001标准；只重新计算该池相同STOP正例保护步长。固定数据、特征、标准化、费用、标签、正则和保护条件不变，改变了该池数值求解程序，必须作为协议修订披露。不能将原225失败算作方法成绩，也不能隐瞒修订只报告成功。','', '## 验证与范围','','独立重算全部有效模型的目标与原始梯度、90条原STOP正例保护、4681个发布前封存预测、21402条三臂保存序列；原208和222控制完整复现。全部有效权重发布后评分，预测发布后连接结果，原225和226保持零外层评分。','', '本次改变拟合支持及辅助风险混合，训练暴露更多，输出不当成STOP校准概率。旧外层反复暴露，只称开发比较；没有新物理、最终8、论文、新FRAME或NN训练。查询和即时收益不等于完整控制时延或整周成本。','', '下一步只读分析两处重复收益、单个大损失与公开输入尺度/数值裕度；在固定新方案前不继续改步长、类别权重或阈值。']
    (O/'GRID227_report.md').write_text('\n'.join(lines)+'\n',encoding='utf8',newline='\n');C.scored();C.save('independent_audit.json',dict(passed=True,all_effective_original_gradient_limits_checked=True,ten_passed_models_andKEEP_byteidentical_to225=True,ninety_original_STOP_positive_constraints_checked=True,all4681_published_predictions_reconstructed=True,all21402_saved_sequences_reconstructed=True,source225_226_noheld_scores=True,all47_effect_changes_and_two_repeated_savings_verified=True,source_hashes_and_publication_barriers_verified=True));C.save('complete.json',dict(passed=True,scope='mixed_context_development_with_explicit_single_pool_numeric_amendment',source225_linear_fits=11,source225_scalar_fits=11,source225_unqualified_not_evaluated=True,source226_single_failed_attempt_preserved=True,new_real_numeric_model_solves=1,new_scalar_recalibrations=1,reused_passed_models=10,constant_KEEP=1,held_predictions=4681,trajectory_rows=21402,new_NN_fits=0,new_physics=0,final8_absent=True));C.archive('audited');dest=R/'论文协作资料/FRAME_辅助经验对照_GRID227';dest.mkdir(exist_ok=False)
